        return ResponseEntity.status(status).body(detail);
    }

    /**
     * Handles {@link InvalidEmailException} thrown when an owner's email is present but is not a
     * syntactically valid address. Returns a 400 Bad Request whose {@code errors} array names the
     * {@code email} field.
     *
     * @param e The {@link InvalidEmailException} to be handled
